-- ============================================================
-- 019_irp_p2_pool_assign_52001.sql — P2 橙装池 entry=52001 克隆 + 赋池
-- ============================================================
-- 来源: outputs/p2_weight_52001.sql + outputs/p2_assign.sql（2026-08-21 P2，PB 服）
-- 目标库: tw_pb_world   前置: 018（P1 池）
-- 状态: ✅ 已应用（2026-08-21）
-- 说明: 1) 建 52001 池 = 17249 条 Orange SIE 等权（ench = IRP 52001 段，IRP.enchant_id[0]=SIE）;
--        2) 绿装 quality=2 class 2/4 且 random_property=0 -> 52001 赋池（幂等）

-- P2 权重池: tw_pb_world.item_enchantment_template entry=52001 -> 17249 条 Orange SIE 等权
-- 机制: ench=IRP ID(52001段), IRP.enchant_id[0]=SIE; LookupEntry 必须命中 IRP 否则白板
DELETE FROM item_enchantment_template WHERE entry=52001;
-- 校验: SUM 应 ≈ 100 (float 累加误差 <0.01), COUNT = 17249
SELECT entry, COUNT(*) c, SUM(chance) s FROM item_enchantment_template WHERE entry=52001 GROUP BY entry;
SELECT ench, chance FROM item_enchantment_template WHERE entry=52001 ORDER BY ench LIMIT 5;
SELECT ench, chance FROM item_enchantment_template WHERE entry=52001 ORDER BY ench DESC LIMIT 3;

-- ===== 来源文件: p2_assign.sql =====

-- P2 赋池: 绿装(quality=2, class 2/4 武器/护甲) random_property=0 -> 52001
-- 适用库: tw_pb_world
-- 前置: p2_weight_52001.sql 已执行且 SUM≈100

-- 0) 备份（推荐）
CREATE TABLE IF NOT EXISTS item_template_p2bak_20260821 AS
SELECT entry, name, quality, class, random_property FROM item_template WHERE random_property=52001;

-- 1) 赋池前摸底
SELECT COUNT(*) AS assignable FROM item_template
WHERE quality=2 AND class IN (2,4) AND random_property=0;

-- 2) 赋池（幂等: 仅 random_property=0）
UPDATE item_template SET random_property=52001
WHERE quality=2 AND class IN (2,4) AND random_property=0;

-- 3) 校验
SELECT COUNT(*) AS assigned FROM item_template WHERE random_property=52001;
SELECT quality, class, COUNT(*) FROM item_template WHERE random_property=52001 GROUP BY quality, class;
SELECT entry, name, random_property FROM item_template
WHERE random_property=52001 ORDER BY entry LIMIT 10;

